import pandas as pd


def run(inputs: dict) -> dict:
    target = inputs["target_snapshot"].copy()
    cdc = inputs["cdc_events"].copy()

    # Build per-device watermark and current reading maps from target_snapshot.
    # If duplicate device_id rows exist, later rows (by original order) win.
    watermark = {}
    reading_map = {}
    for _, row in target.iterrows():
        device_id = row["device_id"]
        watermark[device_id] = row["applied_event_ts"]
        reading_map[device_id] = row["reading"]

    # Determine which cdc events qualify for their device:
    # event_ts must be STRICTLY greater than the device's current watermark.
    # Devices with no existing watermark (new devices) qualify unconditionally.
    def qualifies(row):
        device_id = row["device_id"]
        if device_id in watermark:
            wm = watermark[device_id]
            if pd.isna(wm):
                return True
            event_ts = row["event_ts"]
            if pd.isna(event_ts):
                return False
            return event_ts > wm
        return True

    if not cdc.empty:
        mask = cdc.apply(qualifies, axis=1)
        qualified = cdc[mask].copy()
    else:
        qualified = cdc.copy()

    # Among surviving events per device, latest by (event_ts, event_seq) wins.
    # Deterministic tie-break: stable sort preserves original row order, and
    # among exact ties on (event_ts, event_seq), the row that appears last
    # in the original ordering is the winner.
    winners_dict = {}
    if not qualified.empty:
        qualified_sorted = qualified.sort_values(
            by=["device_id", "event_ts", "event_seq"],
            kind="mergesort",
        )
        winners = qualified_sorted.groupby("device_id", as_index=False).tail(1)
        for _, row in winners.iterrows():
            winners_dict[row["device_id"]] = (row["reading"], row["event_ts"])

    # Union of all device ids: existing snapshot devices + any device_ids seen in cdc.
    all_device_ids = set(watermark.keys())
    if not cdc.empty:
        all_device_ids |= set(cdc["device_id"].unique())

    result_rows = []
    for device_id in sorted(all_device_ids, key=lambda x: (str(type(x)), x)):
        if device_id in winners_dict:
            reading, applied_ts = winners_dict[device_id]
        elif device_id in reading_map:
            reading = reading_map[device_id]
            applied_ts = watermark[device_id]
        else:
            # Should not happen: device only appears in cdc but had no
            # qualifying event and no prior snapshot entry.
            continue

        result_rows.append(
            {
                "device_id": device_id,
                "reading": reading,
                "applied_event_ts": applied_ts,
            }
        )

    new_snapshot = pd.DataFrame(
        result_rows, columns=["device_id", "reading", "applied_event_ts"]
    )

    return {"new_snapshot": new_snapshot}
